const map = L.map('map', {
      zoomControl:false,
      center:[-6.16,106.88],
      zoom:8,
      attributionControl:true
    });

    const coordsControl = document.getElementById('coordsControl');
    map.on('mousemove', e => {
      coordsControl.textContent = `Lat: ${e.latlng.lat.toFixed(6)} | Lng: ${e.latlng.lng.toFixed(6)}`;
    });

    const baseMaps = {
      "OpenStreetMap": L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{
        maxZoom:19, attribution:'© OpenStreetMap contributors'
      }),
      "Light": L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',{
        maxZoom:20, attribution:'© OpenStreetMap © CARTO'
      }),
      "Esri Street": L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{
        maxZoom:19, attribution:'Tiles © Esri'
      }),
      "Esri Satellite": L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{
        maxZoom:19, attribution:'Tiles © Esri'
      }),
      "Dark": L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',{
        maxZoom:20, attribution:'© OpenStreetMap © CARTO'
      })
    };
    baseMaps["OpenStreetMap"].addTo(map);

    // Selector basemap dibuat tanpa thumbnail eksternal agar panel lebih ringan.
    const baseIcons = {
      "OpenStreetMap":"🗺️",
      "Light":"◻",
      "Esri Street":"▦",
      "Esri Satellite":"🌍",
      "Dark":"◼"
    };

    const basemapPanel = document.getElementById('basemapPanel');
    Object.keys(baseMaps).forEach((name,i)=>{
      const row=document.createElement('button');
      row.type='button';
      row.className='base-item'+(i===0?' active':'');
      row.innerHTML=`
        <span class="base-symbol">${baseIcons[name]}</span>
        <span class="base-name">${name}</span>
        <span class="base-radio" aria-hidden="true"></span>`;
      row.onclick=()=>{
        Object.values(baseMaps).forEach(layer=>map.removeLayer(layer));
        baseMaps[name].addTo(map);
        document.querySelectorAll('.base-item').forEach(x=>x.classList.remove('active'));
        row.classList.add('active');
        basemapPanel.classList.remove('open');
        document.body.classList.remove('basemap-mobile-open');
      };
      basemapPanel.appendChild(row);
    });

    const normalChurchIcon = L.divIcon({
      className:'church-marker',
      html:'<div style="width:17px;height:17px;border-radius:50%;background:#fff;border:3px solid #f51b78;box-shadow:0 0 0 1px rgba(245,27,120,.35),0 3px 7px rgba(0,0,0,.18)"></div>',
      iconSize:[20,20],iconAnchor:[10,10],popupAnchor:[0,-10]
    });

    const filteredChurchIcon = L.divIcon({
      className:'church-marker',
      html:'<div style="width:17px;height:17px;border-radius:50%;background:#f51b78;border:3px solid #fff;box-shadow:0 0 0 1.5px #f51b78,0 3px 7px rgba(0,0,0,.18)"></div>',
      iconSize:[20,20],iconAnchor:[10,10],popupAnchor:[0,-10]
    });

    let geoData=null;
    let allFeatures=[];
    let visibleLayer=L.layerGroup().addTo(map);
    let currentFilterActive=false;
    map._fitAfterFilter=false;

    const esc = value => String(value ?? '-')
      .replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')
      .replaceAll('"','&quot;').replaceAll("'","&#039;");

    function prop(p,...keys){
      for(const k of keys) if(p && p[k]!==undefined && p[k]!==null && String(p[k]).trim()!=='') return p[k];
      return '';
    }

    function coordsOf(f){
      const p=f.properties||{};
      let lat=parseFloat(prop(p,'Y','LAT','Latitude','latitude'));
      let lng=parseFloat(prop(p,'X','LON','LNG','Longitude','longitude'));
      if(Number.isFinite(lat)&&Number.isFinite(lng)) return [lat,lng];
      if(f.geometry && f.geometry.type==='Point' && Array.isArray(f.geometry.coordinates))
        return [f.geometry.coordinates[1],f.geometry.coordinates[0]];
      return null;
    }

    function churchName(p){ return prop(p,'NAMA_JEMAA','NAMA_JEMAAT','NAMA_JEMA','NAMA') || 'Gereja'; }
    function address(p){ return prop(p,'ALAMAT_GER','ALAMAT_GEREJA','ALAMAT') || '-'; }
    function pastor(p){ return prop(p,'NAMA_GEMBA','NAMA_GEMBALA','GEMBALA') || '-'; }
    function phone(p){ return prop(p,'NO_HP_WA_G','NO_HP_WA','NO_HP','TELEPON') || '-'; }
    function mawil(p){ return prop(p,'MAWIL','Mawil','MAWIL_') || '-'; }

    function googleMapsUrl(lat,lng){
      return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(lat+','+lng)}`;
    }

    // Nama file foto yang tersedia di folder FotoGereja.
    // GeoJSON tidak memiliki kolom FOTO, jadi foto dicocokkan otomatis berdasarkan ID gereja.
    const churchPhotos = {
      "119":"gereja_119.jpg",
      "121":"gereja_121.png",
      "122":"gereja_122.png",
      "123":"gereja_123.png",
      "126":"gereja_126.jpg",
      "130":"gereja_130.png",
      "132":"gereja_132.png",
      "137":"gereja_137.jpg",
      "138":"gereja_138.jpg",
      "140":"gereja_140.png"
    };

    function photoPath(p){
      const explicit=prop(p,'FOTO','FOTO_GEREJA','foto');
      if(explicit) return 'FotoGereja/'+String(explicit).replace(/^.*[\\\\/]/,'');
      const id=String(prop(p,'ID','OBJECTID','id')).trim();
      return churchPhotos[id] ? 'FotoGereja/'+churchPhotos[id] : '';
    }

    function openDetailsByIndex(index){
      const feature=allFeatures[index];
      if(feature) openDetails(feature);
    }

    function openDetails(feature){
      const p=feature.properties||{}, c=coordsOf(feature);
      const lat=c ? c[0] : '', lng=c ? c[1] : '';
      document.getElementById('modalTitle').textContent=churchName(p);

      const src = photoPath(p);
      const photoBox=document.getElementById('photoBox');
      const mapsLink=document.getElementById('mapsLink');
      photoBox.style.display='grid';
      mapsLink.style.display='block';
      if(src){
        photoBox.innerHTML=`<img src="${esc(src)}" alt="Foto ${esc(churchName(p))}"
          onerror="this.onerror=null;this.parentElement.innerHTML='<div style=\'padding:20px;text-align:center\'>Foto gereja belum tersedia</div>'">`;
      }else{
        photoBox.innerHTML='<div style="padding:20px;text-align:center">Foto gereja belum tersedia</div>';
      }

      const rows=[
        ['📍 Alamat',address(p)],
        ['👤 Gembala',pastor(p)],
        ['☎ No. HP/WA',phone(p)],
        ['🕘 Jam Operasional',prop(p,'Jam_Operas','JAM_OPERASIONAL') || '-'],
        ['🧭 Mawil',mawil(p)]
      ];
      document.getElementById('modalDetails').innerHTML=rows.map(r=>
        `<div class="detail-row"><b>${r[0]}</b><span>${esc(r[1])}</span></div>`).join('');

      const link=document.getElementById('mapsLink');
      link.href=c?googleMapsUrl(lat,lng):'#';
      link.style.pointerEvents=c?'auto':'none';
      link.style.opacity=c?'1':'.5';
      document.getElementById('modalBackdrop').classList.add('show');
      // Detail boleh dibuka saat Cari/Filter/Basemap sedang aktif.
      // Tutup popup Leaflet saja agar modal fokus, tanpa mengubah fitur yang sedang dipakai.
      map.closePopup();
    }

    function popupHTML(feature){
      const p=feature.properties||{}, c=coordsOf(feature);
      return `<div class="popup">
        <h3>${esc(churchName(p))}</h3>
        <p><b>Alamat:</b> ${esc(address(p))}</p>
        <p><b>Gembala:</b> ${esc(pastor(p))}</p>
        <p><b>Mawil:</b> ${esc(mawil(p))}</p>
        <button class="detail-btn" onclick="openDetailsByIndex(${allFeatures.indexOf(feature)})">Lihat Selengkapnya</button>
      </div>`;
    }

    window.__churchFeatures=[];

    function render(features){
      visibleLayer.clearLayers();
      window.__churchFeatures=features;
      const markers=[];
      features.forEach(f=>{
        const c=coordsOf(f); if(!c) return;
        const m=L.marker(c,{icon:currentFilterActive ? filteredChurchIcon : normalChurchIcon});
        m.bindPopup(popupHTML(f),{
          autoPan:true,
          autoPanPaddingTopLeft:[18,128],
          autoPanPaddingBottomRight:[18,28],
          keepInView:true
        });
        m.addTo(visibleLayer);
        markers.push(m);
      });
      document.getElementById('filterStat').textContent=features.length;
      // Tampilan awal sengaja menggunakan cakupan yang lebih luas agar persebaran gereja terlihat.
      if(features.length && map._fitAfterFilter){
        map.fitBounds(L.featureGroup(markers).getBounds().pad(.18));
      }
    }

    // Cakupan Mawil ditulis berdasarkan alamat gereja yang ada pada dataset,
    // bukan sebagai batas administrasi resmi.
    const mawilDescriptions = {
      "1": "Jakarta Pusat — terutama kawasan Kemayoran, Kramat, Senen dan sekitarnya.",
      "2": "Jakarta Utara, Jakarta Barat, dan Bekasi — antara lain Tanjung Priok, Kelapa Gading, Kapuk/Cengkareng, dan Bekasi.",
      "3": "Jakarta Barat — terutama kawasan Cengkareng, Kapuk, dan sekitarnya.",
      "4": "Jakarta Timur, Depok, dan sekitar Cibinong/Bogor — antara lain Cawang, Cakung/Pulo Gebang, Depok, dan Cibinong."
    };

    function updateMawilInfo(value){
      const box=document.getElementById('mawilInfo');
      const title=document.getElementById('mawilInfoTitle');
      const scope=document.getElementById('mawilInfoScope');

      if(!value){
        box.hidden=true;
        return;
      }

      title.textContent='Mawil '+value;
      scope.textContent=mawilDescriptions[String(value)] || 'Cakupan wilayah mengikuti alamat gereja pada data.';
      box.hidden=false;
    }

    function updateStats(){
      document.getElementById('totalStat').textContent=allFeatures.length;
      document.getElementById('filterStat').textContent=allFeatures.length;
      const regions=new Set(allFeatures.map(f=>mawil(f.properties||{})).filter(x=>x&&x!=='-'));
      document.getElementById('wilayahStat').textContent=regions.size;
      const sel=document.getElementById('wilayahSelect');
      [...regions].sort((a,b)=>String(a).localeCompare(String(b),undefined,{numeric:true}))
        .forEach(x=>{
          const o=document.createElement('option');
          o.value=x;
          o.textContent='Mawil '+x;
          sel.appendChild(o);
        });
    }

    function applyFilter(){
      const q=document.getElementById('searchInput').value.trim().toLowerCase();
      const w=document.getElementById('wilayahSelect').value;
      updateMawilInfo(w);
      const filtered=allFeatures.filter(f=>{
        const p=f.properties||{};
        const hay=[churchName(p),address(p),pastor(p),phone(p),mawil(p)].join(' ').toLowerCase();
        return (!q || hay.includes(q)) && (!w || String(mawil(p))===w);
      });
      currentFilterActive=Boolean(q || w);
      map._userMoved=false;
      map._fitAfterFilter=true;
      render(filtered);
    }

    fetch('gereja.geojson')
  .then(r=>{if(!r.ok) throw new Error('File gereja.geojson tidak ditemukan'); return r.json()})
  .then(data=>{
    geoData=data;
    allFeatures=Array.isArray(data.features)?data.features:[];
    updateStats();
    map._fitAfterFilter=true;
    render(allFeatures);
  })
      .catch(err=>{
        console.error(err);
        alert('Gagal membaca gereja.geojson. Pastikan index.html dan gereja.geojson berada dalam folder yang sama dan WebGIS dibuka melalui Live Server.');
      });

    function openAbout(){
      document.getElementById('modalTitle').textContent='Tentang WebGIS';
      const photoBox=document.getElementById('photoBox');
      const mapsLink=document.getElementById('mapsLink');
      photoBox.style.display='none';
      mapsLink.style.display='none';

      document.getElementById('modalDetails').innerHTML=`
        <div class="about-content">
          <p class="about-lead">
            WebGIS ini dirancang sebagai media visualisasi untuk menampilkan persebaran
            Gereja Gerakan Pentakosta di DKI Jakarta dan sekitarnya secara interaktif.
          </p>

          <div class="about-section">
            <h3>🎯 Latar Belakang</h3>
            <p>
              Data gereja yang tersimpan dalam basis data spasial disajikan dalam bentuk
              peta digital agar lokasi dan informasi atribut setiap gereja dapat dilihat
              dengan lebih mudah dan terstruktur.
            </p>
          </div>

          <div class="about-section">
            <h3>🗺️ Tujuan</h3>
            <p>
              WebGIS bertujuan membantu pengguna mengetahui persebaran gereja,
              mencari gereja berdasarkan nama atau alamat, menyaring berdasarkan
              wilayah/Mawil, serta melihat lokasi gereja langsung pada peta.
            </p>
          </div>

          <div class="about-section">
            <h3>📍 Pengertian Mawil</h3>
            <p>
              <b>Mawil</b> merupakan singkatan dari <b>Majelis Wilayah</b>, yaitu pengelompokan
              wilayah pelayanan gereja yang digunakan dalam data WebGIS ini. Pembagian yang
              ditampilkan terdiri atas Mawil 1, Mawil 2, Mawil 3, dan Mawil 4.
            </p>
            <p style="margin-top:8px">
              <b>Cakupan:</b> Mawil 1 meliputi Jakarta Pusat dan sekitarnya; Mawil 2 meliputi
              Jakarta Utara, Jakarta Barat, dan Bekasi; Mawil 3 terutama meliputi kawasan
              Jakarta Barat; sedangkan Mawil 4 meliputi Jakarta Timur, Depok, serta sekitar
              Cibinong/Bogor. Cakupan ini mengikuti alamat gereja pada dataset, bukan batas
              administrasi resmi.
            </p>
          </div>

          <div class="about-section">
            <h3>📊 Data dan Fitur</h3>
            <p>
              Informasi utama bersumber dari <b>gereja.geojson</b>. Peta menyediakan
              pencarian, filter wilayah, pilihan basemap, popup informasi, detail
              gereja, dan akses lokasi melalui Google Maps.
            </p>
          </div>

          <div class="about-maker">
            <div class="about-maker-title">Dibuat oleh</div>
            <div class="about-maker-name">Farhana Fuad | 21110123140147</div>
            <div class="about-maker-role">Teknik Geodesi Universitas Diponegoro</div>
          </div>

          <div class="about-profile-grid">
            <div class="about-person">
              <h4>Pembimbing Kerja Praktik</h4>
              <div class="person-name">Shofiyatul Qoyimah, S.T., M.Eng.</div>
              <div class="person-extra">NIP. H.7.1993042820221001</div>
            </div>

            <div class="about-person">
              <h4>Pembimbing Kerja Praktik Instansi / Perusahaan</h4>
              <div class="person-name">Anita Fatmawaty Effendi, S.T.</div>
              <div class="person-role"><i>Solution Engineer</i> Divisi Data dan <i>Software</i></div>
            </div>

            <div class="about-instansi">
              <img class="about-instansi-logo"
                   src="data:image/png;base64,"
                   alt="Logo PT Waindo SpecTerra">
              <div class="about-instansi-copy">
                <h4>Instansi Kerja Praktik</h4>
                <div class="about-instansi-name">PT Waindo SpecTerra</div>
                <div class="about-instansi-desc">Total solution for digital information</div>
              </div>
            </div>

          </div>
        </div>`;

      document.getElementById('modalBackdrop').classList.add('show');
    }

    /* UI EVENTS */
    document.getElementById('zoomIn').onclick=()=>map.zoomIn();
    document.getElementById('zoomOut').onclick=()=>map.zoomOut();

    const basemapPanelEl=document.getElementById('basemapPanel');
    document.getElementById('layerBtn').onclick=()=>{
      basemapPanelEl.classList.toggle('open');
    };
    document.getElementById('baseClose').onclick=()=>basemapPanelEl.classList.remove('open');

    const searchInput=document.getElementById('searchInput');
    const wilayahSelect=document.getElementById('wilayahSelect');

    document.getElementById('menuSearch').onclick=()=>searchInput.focus();
    document.getElementById('menuFilter').onclick=()=>wilayahSelect.focus();
    document.getElementById('menuAbout').onclick=()=>openAbout();

    document.getElementById('menuAll').onclick=()=>{
  searchInput.value='';
  wilayahSelect.value='';
  updateMawilInfo('');
  currentFilterActive=false;
  map._fitAfterFilter=true;
  render(allFeatures);
};

    searchInput.addEventListener('input',applyFilter);
    wilayahSelect.addEventListener('change',applyFilter);

    document.getElementById('modalClose').onclick=()=>document.getElementById('modalBackdrop').classList.remove('show');
    document.getElementById('modalBackdrop').addEventListener('click',e=>{
      if(e.target.id==='modalBackdrop') e.currentTarget.classList.remove('show');
    });

    document.addEventListener('keydown',e=>{
      if(e.key==='Escape'){
        basemapPanelEl.classList.remove('open');
        document.getElementById('modalBackdrop').classList.remove('show');
      }
    });

    map.on('movestart',()=>map._userMoved=true);
    L.control.scale({imperial:true,metric:true,position:'bottomleft'}).addTo(map);

    const menuToggle = document.getElementById('menuToggle');
    const drawer = document.getElementById('drawer');
    if (menuToggle && drawer) {
      menuToggle.addEventListener('click', () => {
        drawer.classList.toggle('open');
      });
    }
